files.content:
html,
body {
  height: 100%;
  font-family: 'Open Sans', sans-serif;
}

body {
  min-width: 850px;
  margin: 0;
}

.header {
  position: relative;
  display: flex;
  place-items: center;
  box-sizing: border-box;
  width: 100%;
  min-height: 500px;
  padding: 50px 0;
  background: url(./images/background.jpg) no-repeat center / cover;
}

.header-title {
  width: 70%;
  max-width: 560px;
  margin: 0 auto;
  color: white;
  font-size: 60px;
  text-align: center;
  text-transform: uppercase;
}

.header::before {
  content: '';
  position: absolute;
  inset: 0;
  background-color: rgb(0 0 0 / 0.5);
}
